#include <bits/stdc++.h>
#define pair_int pair<int,int>
#define clear_array(a,x) memset(a,x,sizeof(a))
#define make_pair std::make_pair
#define first_element first
#define second_element second
using namespace std;
typedef long long long_long;
typedef unsigned long long ull_type;
typedef unsigned int uint_type;
typedef long double long_double;
const int max_size=55, max_time=2*max_size, max_points=max_time*max_size, max_edges=5*max_time*max_size*max_size;
const int infinity=1e9;

inline char get_char(){
	return getchar();
	static const int buffer_size=1<<16; static char buffer[buffer_size],*ptr=buffer,*end=buffer;
    return ptr==end&&(end=(ptr=buffer)+fread(buffer,1,buffer_size,stdin),ptr==end)?EOF:*ptr++;
}
inline long_long read_long(){
    long_long result=0; char c=get_char(); bool neg=false;
    while(c<'0'||c>'9'){if(c=='-') neg=true;c=get_char();}
    while(c>='0'&&c<='9') result=(result<<1)+(result<<3)+c-'0',c=get_char();
    return neg?(~result+1):result;
}

struct Edge{
	int to,bottom,length,ne;
}edges[max_edges];
int edge_count=1,head[max_points];
int total_nodes,N,M,K,C,D,cnt[max_size];
int node_id[max_size][max_time],start_node=1,end_node=2,point_count=2;
bool visited[max_points];
int dist[max_points],total_cost;
queue<int> q;

inline void add_edge(int a,int b,int c,int l){
	edges[++edge_count].to=b; edges[edge_count].ne=head[a]; head[a]=edge_count;
	edges[edge_count].length=c; edges[edge_count].bottom=l;
}

inline void add_bidirectional_edge(int a,int b,int c,int l){
	add_edge(a,b,c,l);
	add_edge(b,a,-c,0);
}

inline bool spfa(){
	for(int i=1;i<=point_count;i++) visited[i]=false,dist[i]=infinity;
	dist[start_node]=0; q.push(start_node);
	while(!q.empty()){
		int p=q.front(); q.pop();
		visited[p]=false;
		for(int i=head[p];i;i=edges[i].ne){
			if(!edges[i].bottom) continue;
			int b=edges[i].to;
			if(dist[b]>dist[p]+edges[i].length){
				dist[b]=dist[p]+edges[i].length;
				if(!visited[b]) q.push(b), visited[b]=true;
			}
		}
	}
	return dist[end_node]<infinity;
}

int dinic(int x,int flow){
	if(x==start_node) return flow;
	visited[x]=true;
	int remaining=flow;
	for(int i=head[x];i;i=edges[i].ne){
		int b=edges[i].to;
		if(visited[b]||!edges[i^1].bottom||dist[x]<dist[b]+edges[i^1].length) continue;
		int pushed=dinic(b,min(remaining,edges[i^1].bottom));
		if(pushed){
			remaining-=pushed;
			edges[i^1].bottom-=pushed;
			edges[i].bottom+=pushed;
			if(!remaining) break;
		}
	}
	return flow-remaining;
}

int main(){
    N=read_long(); M=read_long(); K=read_long(); C=read_long(); D=read_long();
    for(int i=1;i<=K;i++) cnt[read_long()]++;
    for(int i=1;i<=N;i++){
    	for(int j=1;j<=K+M+2;j++){
    		node_id[i][j]=++point_count;
    		if(i==1) add_edge(node_id[i][j],end_node,C*(j-1),infinity);
    		if(j>1) add_edge(node_id[i][j-1],node_id[i][j],0,infinity);
    	}
    	if(cnt[i]) add_edge(start_node,node_id[i][1],0,cnt[i]);
    }
    for(int i=1;i<=M;i++){
    	int a=read_long(),b=read_long();
    	for(int j=1;j<=K+M+1;j++){
    		for(int k=1;k<=2*K-1;k+=2){
    			add_edge(node_id[a][j],node_id[b][j+1],k*D,1);
    			add_edge(node_id[b][j],node_id[a][j+1],k*D,1);
    		}
    	}
    }
    int total_flow=0;
    while(spfa()){
    	int flow_value=-1;
    	while(flow_value){
    		clear_array(visited,0);
    		flow_value=dinic(end_node,infinity);
    		total_flow+=flow_value;
    		total_cost+=dist[end_node]*flow_value;
    	}
    }
    assert(total_flow==K);
	printf("%d\n",total_cost);
    return 0;
}
